code.cpp:
class Solution {
public:
    string modifyString(string s) {
        int n = s.size();
        for (int i = 0; i < n; i++) {
            if (s[i] == '?') {
                for (char c = 'a'; c <= 'z'; c++) {
                    bool okLeft = (i == 0) || (s[i - 1] != c);
                    bool okRight = (i == n - 1) || (s[i + 1] != c);
                    if (okLeft && okRight) {
                        s[i] = c;
                        break;
                    }
                }
            }
        }
        return s;
    }
};
